using System;
using System.Security.Cryptography;
using System.Text;
using RimWorldLLM.Bridge;
using Xunit;

namespace RimWorldLLM.Tests
{
    // Golden matrices come from segno (see QrCodeGolden.cs, generated by qrref/gen.py).
    public partial class QrCodeTests
    {
        static QrEcc E(string s) { return (QrEcc)Enum.Parse(typeof(QrEcc), s); }

        static string Rows(QrCode q)
        {
            var sb = new StringBuilder();
            for (int y = 0; y < q.Size; y++)
            {
                if (y > 0) sb.Append('/');
                for (int x = 0; x < q.Size; x++) sb.Append(q.Get(x, y) ? '1' : '0');
            }
            return sb.ToString();
        }

        [Fact]
        public void ForcedMaskAndVersionMatchSegno()
        {
            var bad = new StringBuilder();
            foreach (var g in Golden)
            {
                if (!g.Forced) continue;   // auto-mask cases are in AutoMaskAndVersionMatchSegnoAuto
                var q = QrCode.Encode(Str(g.Key), E(g.Ecc), g.Version, g.Mask);
                Assert.Equal(g.Version, q.Version);
                if (g.Rows != Rows(q)) bad.Append(g.Key + " " + g.Ecc + " v" + g.Version + " mask " + g.Mask + "; ");
            }
            Assert.Equal("", bad.ToString());
        }

        [Fact]
        public void AutoMaskAndVersionMatchSegnoAuto()
        {
            foreach (var g in Golden)
            {
                if (g.Forced) continue;
                var q = QrCode.Encode(Str(g.Key), E(g.Ecc));
                Assert.Equal(g.Version, q.Version);
                Assert.Equal(g.Mask, q.Mask);
                Assert.True(g.Rows == Rows(q), g.Key + " " + g.Ecc);
            }
        }

        [Fact]
        public void EveryVersionAndLevelMatchesSegnoHash()
        {
            foreach (var h in Hashes)
            {
                var q = QrCode.Encode("rw" + h.Version, E(h.Ecc), h.Version, 0);
                var hash = BitConverter.ToString(SHA256.Create().ComputeHash(Encoding.ASCII.GetBytes(Rows(q)))).Replace("-", "").ToLowerInvariant();
                Assert.Equal(h.Hash, hash.Substring(0, 16));
            }
        }

        [Fact]
        public void SizeIs17Plus4TimesVersion()
        {
            for (int v = 1; v <= 40; v++)
                Assert.Equal(17 + 4 * v, QrCode.Encode("a", QrEcc.Low, v, 0).Size);
        }

        [Fact]
        public void SmallestVersionIsChosen()
        {
            Assert.Equal(1, QrCode.Encode("HI").Version);
            Assert.Equal(2, QrCode.Encode(new string('a', 15), QrEcc.Medium).Version);   // v1-M holds 14 bytes
            Assert.Equal(1, QrCode.Encode(new string('a', 14), QrEcc.Medium).Version);
        }

        [Fact]
        public void FinderPatternsPresent()
        {
            var q = QrCode.Encode("http://192.168.1.20:47480/engine/v1/hello");
            int[] ox = { 0, q.Size - 7, 0 }, oy = { 0, 0, q.Size - 7 };
            for (int f = 0; f < 3; f++)
                for (int dy = 0; dy < 7; dy++)
                    for (int dx = 0; dx < 7; dx++)
                    {
                        bool ring = dx == 0 || dx == 6 || dy == 0 || dy == 6;
                        bool core = dx >= 2 && dx <= 4 && dy >= 2 && dy <= 4;
                        Assert.Equal(ring || core, q.Get(ox[f] + dx, oy[f] + dy));
                    }
            Assert.False(q.Get(-1, 0));
            Assert.False(q.Get(0, q.Size));
        }

        [Fact]
        public void TooLongThrows()
        {
            Assert.Throws<ArgumentException>(() => QrCode.Encode(new string('a', 2954), QrEcc.Low));
            Assert.Equal(40, QrCode.Encode(new string('a', 2953), QrEcc.Low).Version);
            Assert.Throws<ArgumentException>(() => QrCode.Encode(new string('a', 20), QrEcc.Medium, 1, -1));
            Assert.Throws<ArgumentException>(() => QrCode.Encode("a", QrEcc.Medium, 41, -1));
            Assert.Throws<ArgumentException>(() => QrCode.Encode("a", QrEcc.Medium, 1, 8));
        }

        [Fact]
        public void ToRgbaSizeColoursAndOrientation()
        {
            var q = QrCode.Encode("HI", QrEcc.Low, 1, 0);
            int scale = 3, quiet = 4, dim = (q.Size + 2 * quiet) * scale;
            var px = QrCode.ToRgba(q, scale);
            Assert.Equal(dim * dim * 4, px.Length);
            // corners are the quiet zone: white
            foreach (int o in new[] { 0, (dim - 1) * 4, (dim * (dim - 1)) * 4, (dim * dim - 1) * 4 })
                Assert.Equal(new byte[] { 255, 255, 255, 255 }, new[] { px[o], px[o + 1], px[o + 2], px[o + 3] });
            // the top-left finder corner is dark, and sits at the TOP of the picture = the LAST rows of the array
            int col = quiet * scale, topRow = dim - 1 - quiet * scale;
            int d = (topRow * dim + col) * 4;
            Assert.Equal(new byte[] { 0, 0, 0, 255 }, new[] { px[d], px[d + 1], px[d + 2], px[d + 3] });
            // bottom-left finder corner (module 0,Size-1) is at array row quiet*scale
            int b = ((quiet * scale) * dim + col) * 4;
            Assert.Equal(0, px[b]);
            // the module right of top-left finder's separator, and a module known light: (7,0) is separator
            int s = (topRow * dim + col + 7 * scale) * 4;
            Assert.Equal(255, px[s]);
            // every module is a uniform scale x scale block
            for (int my = 0; my < q.Size; my++)
                for (int mx = 0; mx < q.Size; mx++)
                {
                    byte want = q.Get(mx, my) ? (byte)0 : (byte)255;
                    for (int sy = 0; sy < scale; sy++)
                        for (int sx = 0; sx < scale; sx++)
                        {
                            int row = dim - 1 - ((my + quiet) * scale + sy);
                            Assert.Equal(want, px[(row * dim + (mx + quiet) * scale + sx) * 4]);
                        }
                }
        }

        [Fact]
        public void ToRgbaNoQuietZone()
        {
            var q = QrCode.Encode("HI");
            Assert.Equal(q.Size * q.Size * 4, QrCode.ToRgba(q, 1, 0).Length);
        }
    }
}
